import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import stringToColor from 'flarum/common/utils/stringToColor';
import { cfg, t } from '../util';

// Where the dots sit: rings at 34% and 66% of the radius, spread around.
const SPOTS = [[62, 14], [24, 28], [74, 56], [36, 70], [14, 54], [50, 40], [82, 32], [58, 80], [28, 84], [44, 22], [86, 70], [70, 90]];

/** Who is online: a count for everyone, faces for visitors allowed to list members. */
export default class Radar extends Component {
  view() {
    const radar = cfg()?.radar;
    if (!radar) return null;
    const shown = radar.users.slice(0, SPOTS.length);
    const more = radar.count - shown.length;
    return m("div", {
      className: "DuskRadar"
    }, m("div", {
      className: "DuskRadar-head"
    }, m("span", {
      className: "DuskRadar-title"
    }, t('radar.title')), m("span", {
      className: "DuskRadar-count"
    }, t('radar.count', {
      count: radar.count
    }))), m("div", {
      className: "DuskRadar-scope",
      role: "img",
      "aria-label": String(t('radar.label', {
        count: radar.count
      }))
    }, m("span", {
      className: "DuskRadar-sweep"
    }), shown.map((u, i) => m(Link, {
      className: "DuskRadar-dot",
      href: app.route('user', {
        username: u.username
      }),
      title: u.displayName,
      style: {
        left: SPOTS[i][0] + '%',
        top: SPOTS[i][1] + '%',
        '--dot': stringToColor(u.username)
      }
    }, u.avatarUrl ? m("img", {
      src: u.avatarUrl,
      alt: u.displayName,
      loading: "lazy"
    }) : m("span", {
      "aria-hidden": "true"
    }, u.displayName.charAt(0).toUpperCase()))), more > 0 && shown.length ? m("span", {
      className: "DuskRadar-more"
    }, "+", more) : null));
  }
}
flarum.reg.add('ernestdefoe-duskline', 'forum/components/Radar', Radar);